14	final class QRScannerViewController: UIViewController {
15	    private let onScan: (String) -> Void
16	    private var captureSession: AVCaptureSession?
17	    private var previewLayer: AVCaptureVideoPreviewLayer?
18	
19	    init(onScan: @escaping (String) -> Void) {
20	        self.onScan = onScan
21	        super.init(nibName: nil, bundle: nil)
22	    }
23	
24	    required init?(coder: NSCoder) { fatalError() }
