26	    override func viewDidLoad() {
27	        super.viewDidLoad()
28	        view.backgroundColor = .black
29	        setupCapture()
30	    }
31	
32	    override func viewDidLayoutSubviews() {
33	        super.viewDidLayoutSubviews()
34	        previewLayer?.frame = view.bounds
35	    }
36	
37	    override func viewWillAppear(_ animated: Bool) {
38	        super.viewWillAppear(animated)
39	        if captureSession?.isRunning == false {
40	            DispatchQueue.global(qos: .userInitiated).async {
41	                self.captureSession?.startRunning()
42	            }
43	        }
44	    }
45	
46	    override func viewWillDisappear(_ animated: Bool) {
47	        super.viewWillDisappear(animated)
48	        if captureSession?.isRunning == true {
49	            captureSession?.stopRunning()
50	        }
51	    }
52	
53	    private func setupCapture() {
54	        guard let device = AVCaptureDevice.default(for: .video),
55	              let input = try? AVCaptureDeviceInput(device: device) else {
56	            showUnavailable()
57	            return
58	        }
59	
60	        let session = AVCaptureSession()
61	        let output = AVCaptureMetadataOutput()
62	
63	        guard session.canAddInput(input), session.canAddOutput(output) else {
64	            showUnavailable()
65	            return
66	        }
67	
68	        session.addInput(input)
69	        session.addOutput(output)
70	        output.setMetadataObjectsDelegate(self, queue: .main)
71	        output.metadataObjectTypes = [.qr]
72	
73	        let preview = AVCaptureVideoPreviewLayer(session: session)
74	        preview.videoGravity = .resizeAspectFill
75	        preview.frame = view.bounds
76	        view.layer.addSublayer(preview)
77	        self.previewLayer = preview
78	        self.captureSession = session
79	
80	        DispatchQueue.global(qos: .userInitiated).async {
81	            session.startRunning()
82	        }
