44	// PrintQR generates and prints the pairing QR code to stdout.
45	// tailscaleHost is optional; if non-empty it's included in the QR URL.
46	func PrintQR(host string, port int, token string, tailscaleHost string) error {
47		if host == "" {
48			host = primaryLANIP()
49		}
50	
51		url := fmt.Sprintf("cmux-bridge://pair?host=%s&port=%d&token=%s", host, port, token)
52		if tailscaleHost != "" {
53			url += "&tailscale_host=" + tailscaleHost
54		}
55	
56		qr, err := qrcode.New(url, qrcode.Medium)
57		if err != nil {
58			return fmt.Errorf("generate qr: %w", err)
59		}
60	
61		art := qr.ToString(false)
62	
63		fmt.Println()
64		fmt.Println("┌─────────────────────────────────────────┐")
65		fmt.Println("│         Scan to pair cmux companion      │")
66		fmt.Println("└─────────────────────────────────────────┘")
67		fmt.Println(art)
68		fmt.Printf("URL: %s\n\n", url)
69	
70		// Make the remote-access state unmistakable — pairing without a tailnet host
71		// is the #1 reason the phone works on Wi-Fi but is stuck "reconnecting" off it.
72		if tailscaleHost != "" {
73			fmt.Printf("✓ Remote access: this pairing includes tailnet host %q,\n", tailscaleHost)
74			fmt.Println("  so the phone can reach the bridge off Wi-Fi (needs Tailscale on the phone).")
75		} else {
76			fmt.Println("⚠ LAN ONLY: this pairing has NO Tailscale host — the phone will only")
77			fmt.Println("  connect on the same Wi-Fi and will show \"reconnecting\" elsewhere.")
78			fmt.Println("  For remote access, re-run:  cmux-bridge --pair --tailscale")
79		}
80		fmt.Println()
81	
82		return nil
83	}
