85	// primaryLANIP returns the best non-loopback IPv4 address of this machine.
86	func primaryLANIP() string {
87		ifaces, err := net.Interfaces()
88		if err != nil {
89			return "127.0.0.1"
90		}
91		for _, iface := range ifaces {
92			if iface.Flags&net.FlagUp == 0 || iface.Flags&net.FlagLoopback != 0 {
93				continue
94			}
95			addrs, err := iface.Addrs()
96			if err != nil {
97				continue
98			}
99			for _, addr := range addrs {
100				var ip net.IP
101				switch v := addr.(type) {
102				case *net.IPNet:
103					ip = v.IP
104				case *net.IPAddr:
105					ip = v.IP
106				}
107				if ip == nil || ip.IsLoopback() {
108					continue
109				}
110				if ip4 := ip.To4(); ip4 != nil {
111					return ip4.String()
112				}
113			}
114		}
115		return "127.0.0.1"
116	}
